contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logger, address keepAddress, address requester, bytes32 digest, uint256 utxoSize, bytes memory redeemerOutputScript, uint256 requestedFee, bytes memory outpoint, bytes32 r, bytes32 s, bytes32 pubX, bytes32 pubY, bool wasFraud, bytes32 txid) public {
        require(logger != address(this), "logger must not be test contract");

        bool beforeApproved = c.approvedToLog(logger); if (__ESBMC_reverted()) return;
        require(!beforeApproved, "logger must be unapproved");

        bool resultCreated = c.logCreated(keepAddress); if (__ESBMC_reverted()) return;
        bool afterApproved = c.approvedToLog(logger); if (__ESBMC_reverted()) return;

        bool resultRedemption = c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint); if (__ESBMC_reverted()) return;
        bool resultSignature = c.logGotRedemptionSignature(digest, r, s); if (__ESBMC_reverted()) return;
        bool resultPubkey = c.logRegisteredPubkey(pubX, pubY); if (__ESBMC_reverted()) return;
        bool resultSetupFailed = c.logSetupFailed(); if (__ESBMC_reverted()) return;
        bool resultFraud = c.logFraudDuringSetup(); if (__ESBMC_reverted()) return;
        bool resultFunded = c.logFunded(); if (__ESBMC_reverted()) return;
        bool resultCourtesy = c.logCourtesyCalled(); if (__ESBMC_reverted()) return;
        bool resultLiquidation = c.logStartedLiquidation(wasFraud); if (__ESBMC_reverted()) return;
        bool resultRedeemed = c.logRedeemed(txid); if (__ESBMC_reverted()) return;
        bool resultLiquidated = c.logLiquidated(); if (__ESBMC_reverted()) return;
        bool resultExited = c.logExitedCourtesyCall(); if (__ESBMC_reverted()) return;

        assert(
            resultCreated == false &&
            resultRedemption == false &&
            resultSignature == false &&
            resultPubkey == false &&
            resultSetupFailed == false &&
            resultFraud == false &&
            resultFunded == false &&
            resultCourtesy == false &&
            resultLiquidation == false &&
            resultRedeemed == false &&
            resultLiquidated == false &&
            resultExited == false &&
            c.approvedToLog(logger) == beforeApproved
        );
    }

    receive() external payable {}
}

